/**
 * Dynamic value definitions and template resolution.
 *
 * Every dynamic value is generated by calling the real Rust backend (orbit_dynamic) through the bridge.
 * Template syntax: {{key}} = variable, {{$category.method(args)}} = dynamic value.
 */
import type { DataLocale, HttpRequest, KeyValue } from "@/data/types";

export type Locale = "zh-CN" | "en-US";

export interface DynamicDef {
  category: string;
  method: string;
  /** i18n key of the display label */
  labelKey: string;
  args?: string;
  /** i18n key of the description */
  descKey: string;
  /** Whether every argument is optional (the backend default is used when omitted) */
  argsOptional?: boolean;
  /** i18n key of the default-value note (e.g. "format=yyyy-MM-dd HH:mm:ss"), shown when argsOptional */
  defaultsKey?: string;
  /** Time zone shown in the reference dialog examples (e.g. "Asia/Shanghai"), used by parameterized date entries */
  tzExample?: string;
  /** Locale-sensitive: the output varies with locale (zh/en/ja) and a `locale=` argument is appended when inserting */
  localeSensitive?: boolean;
}

