// ── Dynamic value token construction ───────────────────────────────

/**
 * Build a dynamic value token: locale-sensitive entries append a `locale=` argument for a non-zh data locale.
 * Nothing is appended for the default zh (the backend defaults to zh, keeping tokens short).
 *
 * Example: `fullName` + dataLocale="ja" → `$person.fullName(locale=ja)`
 */
export function buildDynamicToken(
  d: DynamicDef,
  dataLocale: DataLocale = "zh",
): string {
  const localeArg =
    d.localeSensitive && dataLocale !== "zh" ? `locale=${dataLocale}` : null;
  const args = [d.args, localeArg].filter(Boolean).join(", ");
  return args
    ? `$${d.category}.${d.method}(${args})`
    : `$${d.category}.${d.method}`;
}

// ── Dynamic template resolution ───────────────────────────────────

/**
 * Convert `key=value, key2=value2` arguments into the comma-separated string the backend expects.
 * The backend orbit_dynamic parses them with `parse_args`, whose separator is `,`.
 */
function formatArgs(args?: string): string {
  return (args ?? "").trim();
}

/**
 * Asynchronously resolve a template: handle `{{$category.method(args)}}` first (through the bridge to the real backend),
 * then substitute `{{key}}` (environment variables / extracted variables).
 *
 * @param keepDynamic when true, skip the first dynamic-value pass and keep `{{$...}}` verbatim —
 *   used by load tests / scenarios: the backend engine regenerates the value on every request, so all requests do not share one value.
 */
export async function resolveTemplate(
  input: string,
  variables: Record<string, string>,
  _locale: Locale = "zh-CN",
  keepDynamic = false,
): Promise<string> {
  if (!input) return input;

  let result = input;

  // First pass: resolve {{$category.method(args)}} → call the real backend (skipped when keepDynamic,
  // keeping the text for the backend to regenerate per request)
  if (!keepDynamic) {
    // Dynamic import avoids a circular dependency
    const {
      generateDynamicValue: bridgeGen,
      resolveDynamicValues: bridgeResolve,
    } = await import("./bridge");
    // Captures `|` pipes (the pipeline segments are executed entirely on the Rust side)
    const dynamicPattern =
      /\{\{\s*\$([\w-]+)\.([\w-]+)(?:\(([^)]*)\))?(?:\|([^}]+))?\s*\}\}/g;
    const dynamicMatches = [...input.matchAll(dynamicPattern)];

    // When any token has a pipe, hand the whole string to the Rust resolver (keeping pipe and multi-token semantics consistent)
    const hasPipes = dynamicMatches.some((m) => m[4]);
    if (hasPipes) {
      try {
        result = await bridgeResolve(input);
      } catch {
        console.warn(
          "[resolve] failed to resolve a dynamic value (with pipes); keeping the original text",
        );
      }
      return result.replace(/\{\{\s*([\w.-]+)\s*\}\}/g, (_m, varName) => {
        return variables[varName] ?? "";
      });
    }

    for (const m of dynamicMatches) {
      const [full, cat, meth, rawArgs] = m;
      try {
        const value = await bridgeGen(cat, meth, formatArgs(rawArgs));
        result = result.replace(full, value);
      } catch {
        // Keep the placeholder verbatim when the backend call fails
        console.warn(
          `[resolve] dynamic value generation failed: $${cat}.${meth}(${rawArgs ?? ""})`,
        );
      }
    }
  }

  // Second pass: resolve {{key}} → variable substitution
  result = result.replace(/\{\{\s*([\w.-]+)\s*\}\}/g, (_m, varName) => {
    return variables[varName] ?? "";
  });

  return result;
}

/**
 * Synchronous template resolution (variable substitution only, no dynamic values).
 * Used by simple cases that need no dynamic values.
 */
export function resolveVariables(
  input: string,
  variables: Record<string, string>,
): string {
  if (!input) return input;
  return input.replace(/\{\{\s*([\w.-]+)\s*\}\}/g, (_m, varName) => {
    return variables[varName] ?? "";
  });
}

/**
 * Extract path parameter names from a URL (`{name}` single-brace placeholders).
 * `{{...}}` templates are removed first (so the inner brace of `{{var}}` is not mistaken for one),
 * then single braces are matched; consecutive placeholders such as `{a}-{b}` are recognized too.
 */
export function extractPathParamNames(url: string): string[] {
  const noTemplates = url.replace(/\{\{[^{}]*\}\}/g, "");
  const names: string[] = [];
  const re = /\{([^{}]+)\}/g;
  for (const m of noTemplates.matchAll(re)) {
    const n = m[1].trim();
    if (n) names.push(n);
  }
  return [...new Set(names)];
}

/**
 * Resolve a URL and apply path parameters: resolve the template first, then replace each `{name}` placeholder with
 * the matching pathParams value (only non-empty values are substituted and encodeURIComponent-ed; empty values keep the placeholder).
 * @param keepDynamic when true, keep `{{$...}}` dynamic values verbatim (generated by the backend per request)
 */
export async function applyPathParams(
  url: string,
  pathParams: KeyValue[] | undefined,
  variables: Record<string, string>,
  locale: Locale = "zh-CN",
  keepDynamic = false,
): Promise<string> {
  let u = await resolveTemplate(url, variables, locale, keepDynamic);
  for (const p of pathParams ?? []) {
    if (!p.enabled || !p.key) continue;
    const v = await resolveTemplate(p.value, variables, locale, keepDynamic);
    if (v) {
      // No encoding happens when keeping dynamic values ({{$...}}) verbatim: encoding would corrupt placeholders containing % and the like,
      // so the backend resolves them per request instead
      const isDynamic = keepDynamic && v.includes("{{$");
      u = u.split(`{${p.key}}`).join(isDynamic ? v : encodeURIComponent(v));
    }
  }
  return u;
}

// ── Request URL building (shared by one-off sends / load tests / scenario YAML / request detail views) ───────

/** Join query parameter key/value pairs.
 *  With `keepDynamic` true (load tests / scenario YAML), `{{$...}}` dynamic values are not encoded
 *  — a placeholder contains characters such as %, which encoding would corrupt, so the backend engine resolves it per request. */
function joinQuery(
  url: string,
  pairs: { k: string; v: string }[],
  keepDynamic: boolean,
): string {
  if (pairs.length === 0) return url;
  const enc = (s: string) =>
    keepDynamic && s.includes("{{$") ? s : encodeURIComponent(s);
  const qs = pairs.map((p) => `${enc(p.k)}=${enc(p.v)}`).join("&");
  return url + (url.includes("?") ? "&" : "?") + qs;
}

/**
 * Build the final request URL: URL template resolution + path parameters + query parameter joining.
 * Shared by one-off debugging / load tests / the "Request" tab detail view so what is shown matches what is really sent.
 *
 * @param keepDynamic when true, keep `{{$...}}` dynamic values verbatim (load tests: regenerated by the backend per request)
 */
export async function buildRequestUrl(
  req: Pick<HttpRequest, "url" | "pathParams" | "queryParams">,
  variables: Record<string, string>,
  locale: Locale = "zh-CN",
  keepDynamic = false,
): Promise<string> {
  let url = await applyPathParams(
    req.url,
    req.pathParams,
    variables,
    locale,
    keepDynamic,
  );
  const enabledParams = (req.queryParams ?? []).filter(
    (p) => p.enabled && p.key,
  );
  const pairs = await Promise.all(
    enabledParams.map(async (p) => ({
      k: await resolveTemplate(p.key, variables, locale, keepDynamic),
      v: await resolveTemplate(p.value, variables, locale, keepDynamic),
    })),
  );
  return joinQuery(url, pairs, keepDynamic);
}

/**
 * Structural URL building (for scenario YAML): only path / query parameter joining,
 * **without resolving variables** — `{{var}}` / `{{$...}}` placeholders stay verbatim in the YAML and
 * are interpolated by the backend engine on every request (pipeline.interp_value normalizes `{{var}}` → `${var}`,
 * with missing variables left as-is).
 *
 * Encoding heuristic: literal values are encodeURIComponent-ed, while placeholder values containing `{{` are left alone
 * (a placeholder contains characters such as `{ } %`, which encoding would corrupt, so the engine resolves it).
 */
export function buildRequestUrlRaw(
  req: Pick<HttpRequest, "url" | "pathParams" | "queryParams">,
): string {
  const isPlaceholder = (s: string) => s.includes("{{");
  let url = req.url;
  for (const p of req.pathParams ?? []) {
    if (!p.enabled || !p.key) continue;
    const v = p.value ?? "";
    if (v) {
      url = url
        .split(`{${p.key}}`)
        .join(isPlaceholder(v) ? v : encodeURIComponent(v));
    }
  }
  const enabledParams = (req.queryParams ?? []).filter(
    (p) => p.enabled && p.key,
  );
  if (enabledParams.length === 0) return url;
  const enc = (s: string) => (isPlaceholder(s) ? s : encodeURIComponent(s));
  const qs = enabledParams
    .map((p) => `${enc(p.key)}=${enc(p.value)}`)
    .join("&");
  return url + (url.includes("?") ? "&" : "?") + qs;
}
